import torch

def confusion_counts(logits, labels, threshold=0.5):
    if logits.ndim != 2 or logits.shape[1] != 2:
        raise ValueError("expected two-class logits with shape [N, 2]")
    labels = torch.as_tensor(labels, device=logits.device, dtype=torch.long)
    if labels.shape != logits.shape[:1]:
        raise ValueError("labels must have shape [N]")
    if not bool(((labels == 0) | (labels == 1)).all()):
        raise ValueError("labels must contain only 0 and 1")
    if not 0.0 <= float(threshold) <= 1.0:
        raise ValueError("threshold must be between 0 and 1")

    scores = logits.softmax(dim=1)[:, 1]
    predicted = scores >= threshold
    positive = labels == 1
    counts = {
        "tp": int((predicted & positive).sum().item()),
        "fp": int((predicted & ~positive).sum().item()),
        "fn": int((~predicted & positive).sum().item()),
        "tn": int((~predicted & ~positive).sum().item()),
    }
    return counts, scores.detach()

import torch

def make_weighted_cross_entropy(negative_count, positive_count, device="cpu"):
    class_counts = torch.tensor(
        [negative_count, positive_count], dtype=torch.float32
    )
    if (class_counts <= 0).any():
        raise ValueError("each class must occur in the training split")

    class_weights = class_counts.sum() / (2 * class_counts)
    loss_fn = torch.nn.CrossEntropyLoss(weight=class_weights.to(device))
    return loss_fn, class_weights

import torch
from torch.utils.data import DataLoader, WeightedRandomSampler

def make_weighted_loader(dataset, training_labels, class_weights, batch_size=32):
    labels = torch.as_tensor(training_labels, dtype=torch.long, device="cpu")
    weights = torch.as_tensor(class_weights, dtype=torch.double, device="cpu")
    if labels.ndim != 1 or len(labels) != len(dataset):
        raise ValueError("training_labels must contain one label per dataset item")
    if labels.numel() == 0:
        raise ValueError("weighted sampling requires a non-empty dataset")
    if weights.ndim != 1 or len(weights) == 0:
        raise ValueError("class_weights must be a non-empty vector")
    if not bool(torch.isfinite(weights).all()) or bool((weights <= 0).any()):
        raise ValueError("class_weights must be finite and positive")
    if labels.numel():
        smallest = int(labels.min().item())
        largest = int(labels.max().item())
        if smallest < 0 or largest >= len(weights):
            raise ValueError("training label is outside the class-weight range")

    example_weights = weights[labels]
    sampler = WeightedRandomSampler(
        weights=example_weights,
        num_samples=len(labels),
        replacement=True,
        generator=torch.Generator().manual_seed(23),
    )
    return DataLoader(
        dataset, batch_size=batch_size, sampler=sampler, shuffle=False
    )

def make_selection_record(
    checkpoint, threshold, validation_f1, split_revision
):
    return {
        "checkpoint": str(checkpoint),
        "threshold": float(threshold),
        "validation_f1": float(validation_f1),
        "split_revision": str(split_revision),
        "selection_rule": "maximum validation F1",
    }

